import { Component, createMemo } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";

export interface TotIconProps {
	isApexAge: boolean;
	class: string;
}
export const TotIcon: Component<TotIconProps> = (props) => {
	const tooltipTitle = createMemo(() =>
		props.isApexAge ? Locale.stylize("LOC_UI_APEX") : Locale.stylize("LOC_UI_TIME_TESTED"),
	);
	const tooltipText = createMemo(() =>
		props.isApexAge
			? Locale.stylize("LOC_PEDIA_CONCEPTS_APEX_AGE_TOOLTIP")
			: Locale.stylize("LOC_PEDIA_CONCEPTS_TIME_TESTED_TOOLTIP"),
	);
	const iconName = createMemo(() =>
		props.isApexAge ? "url('blp:civ_apex_100x100')" : "url('blp:civ_timetested_100x100')",
	);

	return (
		<Tooltip.Text
			bodyClass="flex flex-row justify-center"
			text={tooltipText()}
			header={tooltipTitle()}
		>
			<Icon
				class={props.class}
				name={iconName()}
				isUrl={true}
			/>
		</Tooltip.Text>
	);
};
